---
import '../styles/global.css';

export interface Props {
  title?: string;
  description?: string;
  activePage?: string;
}

const {
  title = "Katered Kneads — Handmade Campus Cookies",
  description = "Handmade, 100% scratch cookies delivered biweekly to UC Berkeley and UC Davis. Limited preorders open every two weeks.",
  activePage = ""
} = Astro.props;
---

<html lang="en">
  <head>
    <meta charset="utf-8" />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
    <link rel="icon" href="/favicon.ico" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="generator" content={Astro.generator} />
    <meta name="description" content={description} />
    <title>{title}</title>
  </head>
  <body>

    <!-- Mobile Nav Overlay -->
    <div class="mobile-nav" id="mobile-nav" role="dialog" aria-modal="true" aria-label="Mobile navigation">
      <button class="mobile-nav-close" id="mobile-nav-close" aria-label="Close menu">✕</button>
      <a href="/" class="mobile-link">Home</a>
      <a href="/order" class="mobile-link">Order</a>
      <a href="/#how-it-works" class="mobile-link">How It Works</a>
      <a href="/#about" class="mobile-link">About</a>
      <a href="/#contact" class="mobile-link">Contact</a>
    </div>

    <!-- Header -->
    <header id="site-header">
      <div class="nav-inner">
        <a href="/" class="nav-logo" aria-label="Katered Kneads home">Katered Kneads</a>

        <nav class="nav-links" aria-label="Primary navigation">
          <a href="/order" class={activePage === 'order' ? 'nav-active' : ''}>Order</a>
          <a href="/#how-it-works">How It Works</a>
          <a href="/#about">About</a>
          <a href="/#contact">Contact</a>
        </nav>

        <div class="nav-instagram" id="nav-instagram-desktop">
          <a href="https://www.instagram.com/Katered_Kneads" target="_blank" rel="noopener noreferrer" aria-label="Instagram @Katered_Kneads">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <rect x="2" y="2" width="20" height="20" rx="5" ry="5"></rect>
              <path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"></path>
              <line x1="17.5" y1="6.5" x2="17.51" y2="6.5"></line>
            </svg>
          </a>
        </div>

        <button class="hamburger" id="hamburger" aria-label="Open menu" aria-expanded="false">
          <span></span>
          <span></span>
          <span></span>
        </button>
      </div>
    </header>

    <slot />

    <!-- Footer -->
    <footer>
      <div class="footer-inner">
        <div class="footer-newsletter">
          <p class="footer-newsletter-heading">Stay in the loop.</p>
          <p class="footer-newsletter-sub">Follow us on Instagram for drop announcements and behind-the-scenes baking. Or join our SMS list to be texted the moment preorders open.</p>
          <div class="footer-cta-row">
            <a href="https://www.instagram.com/Katered_Kneads" target="_blank" rel="noopener noreferrer" class="cta-link">Instagram @Katered_Kneads →</a>
            <a href="/order#sms-signup" class="cta-link">Join SMS List →</a>
          </div>
        </div>
        <div class="footer-bottom">
          <div class="footer-links">
            <a href="/privacy-policy">Privacy Policy</a>
            <a href="/terms">Terms &amp; Conditions</a>
            <a href="/refund-policy">Refund Policy</a>
          </div>
          <p class="footer-copy">&copy; 2026 Katered Kneads &mdash; UC Berkeley &amp; UC Davis</p>
        </div>
      </div>
    </footer>

    <script>
      // Scroll header border
      const header = document.getElementById('site-header');
      window.addEventListener('scroll', () => {
        header?.classList.toggle('scrolled', window.scrollY > 20);
      }, { passive: true });

      // Hamburger / Mobile Nav
      const hamburger = document.getElementById('hamburger');
      const mobileNav = document.getElementById('mobile-nav');
      const mobileNavClose = document.getElementById('mobile-nav-close');

      function openMobileNav() {
        mobileNav?.classList.add('open');
        hamburger?.setAttribute('aria-expanded', 'true');
        document.body.style.overflow = 'hidden';
      }

      function closeMobileNav() {
        mobileNav?.classList.remove('open');
        hamburger?.setAttribute('aria-expanded', 'false');
        document.body.style.overflow = '';
      }

      hamburger?.addEventListener('click', openMobileNav);
      mobileNavClose?.addEventListener('click', closeMobileNav);
      document.querySelectorAll('.mobile-link').forEach(link => {
        link.addEventListener('click', closeMobileNav);
      });
    </script>

  </body>
</html>

