@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;0,700;1,300;1,400&family=DM+Sans:wght@300;400;500;600&display=swap');
@import "tailwindcss";

:root {
  --bg: #FAF7F2;
  --text-primary: #1A1A1A;
  --text-muted: #6B6B6B;
  --accent: #D9CFC4;
  --max-width: 1100px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg);
  color: var(--text-primary);
  font-family: 'DM Sans', sans-serif;
  font-size: 1rem;
  line-height: 1.7;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Typography */
.font-display {
  font-family: 'Cormorant Garamond', serif;
}

.eyebrow {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.section-heading {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 500;
  line-height: 1.2;
  color: var(--text-primary);
  margin-top: 0.5rem;
}

/* Navigation */
header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background-color: var(--bg);
  border-bottom: 1px solid transparent;
  transition: border-color 0.3s ease;
}

header.scrolled {
  border-bottom-color: var(--accent);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.nav-logo {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.4rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-primary);
  text-decoration: none;
  flex-shrink: 0;
}

.nav-logo img {
  height: 40px;
  width: auto;
}

nav.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

nav.nav-links a {
  font-size: 0.78rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--text-primary);
  position: relative;
  padding-bottom: 2px;
}

nav.nav-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background-color: var(--text-primary);
  transition: width 0.2s ease;
}

nav.nav-links a:hover::after {
  width: 100%;
}

.nav-instagram a {
  color: var(--text-primary);
  text-decoration: none;
  display: flex;
  align-items: center;
}

.nav-instagram a:hover {
  color: var(--text-muted);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background-color: var(--text-primary);
  transition: transform 0.3s ease, opacity 0.3s ease;
}

/* Mobile Nav Overlay */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  background-color: var(--bg);
  z-index: 99;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2rem;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  font-family: 'Cormorant Garamond', serif;
  font-size: 2rem;
  font-weight: 500;
  text-decoration: none;
  color: var(--text-primary);
  letter-spacing: 0.05em;
}

.mobile-nav a:hover {
  color: var(--text-muted);
}

.mobile-nav-close {
  position: absolute;
  top: 1.5rem;
  right: 1.5rem;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--text-primary);
  line-height: 1;
}

/* Hero */
.hero {
  padding-top: 70px;
}

.hero-banner {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.hero-image {
  width: 100%;
  height: clamp(480px, 70vh, 720px);
  object-fit: cover;
  display: block;
  /* lighten the photo so dark text reads clearly */
  filter: brightness(1.15) saturate(0.85);
}

/* warm cream wash over the image */
.hero-banner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(250, 247, 242, 0.45);
  pointer-events: none;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 0 1.5rem 3.5rem;
  max-width: calc(var(--max-width) + 3rem);
  margin: 0 auto;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
}

.hero-headline {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(5rem, 13vw, 9rem);
  font-weight: 600;
  line-height: 0.9;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--text-primary);
  margin: 0.6rem 0 0;
}

/* Below-image content area */
.hero-content {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2.5rem 1.5rem 3rem;
}

.hero-body {
  max-width: 560px;
  color: var(--text-muted);
  font-size: 1rem;
  line-height: 1.75;
}

.hero-body p + p {
  margin-top: 1rem;
}

/* Feature Row */
.features {
  border-top: 1px solid var(--accent);
  margin-top: 3rem;
  padding-top: 2.5rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.feature-item h4 {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--text-primary);
  margin-bottom: 0.3rem;
}

.feature-item p {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* Sections */
.section {
  padding: 6rem 0;
}

.section + .section {
  border-top: 1px solid var(--accent);
}

.section-header {
  margin-bottom: 3.5rem;
}

/* Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 4rem;
}

.step-number {
  font-family: 'Cormorant Garamond', serif;
  font-size: 5rem;
  font-weight: 300;
  line-height: 1;
  color: var(--accent);
  margin-bottom: 1rem;
}

.step h3 {
  font-family: 'DM Sans', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  margin-bottom: 0.6rem;
}

.step p {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.7;
}

.steps-images {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.steps-images img {
  width: 100%;
  height: 360px;
  object-fit: cover;
  display: block;
}

/* Menu */
.menu-status {
  border: 1px solid var(--accent);
  padding: 3rem;
  max-width: 480px;
}

.menu-status .status-label {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

.menu-status h3 {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.75rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.menu-status p {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* Bread collection image */
.section-image {
  width: 100%;
  max-height: 480px;
  object-fit: cover;
  display: block;
  margin: 4rem 0;
}

/* FAQ */
.faq-list {
  border-top: 1px solid var(--accent);
}

.faq-item {
  border-bottom: 1px solid var(--accent);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.4rem 0;
  cursor: pointer;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  gap: 1rem;
}

.faq-question span {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.4;
}

.faq-toggle {
  font-size: 1.2rem;
  font-weight: 300;
  color: var(--text-muted);
  transition: transform 0.25s ease;
  flex-shrink: 0;
  line-height: 1;
}

.faq-item.open .faq-toggle {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.25s ease;
}

.faq-answer-inner {
  padding-bottom: 1.4rem;
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.75;
  max-width: 680px;
}

.faq-item.open .faq-answer {
  max-height: 400px;
}

/* KatBox Section */
.katbox-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.katbox-text p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.75;
}

.katbox-text p + p {
  margin-top: 1rem;
}

.katbox-details {
  border: 1px solid var(--accent);
  padding: 2rem;
}

.katbox-detail-item {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.9rem 0;
  border-bottom: 1px solid var(--accent);
  font-size: 0.875rem;
}

.katbox-detail-item:last-child {
  border-bottom: none;
}

.katbox-detail-label {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.katbox-detail-item span:last-child {
  color: var(--text-primary);
}

/* Monday Sales */
.monday-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.monday-text p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.75;
}

.monday-text p + p {
  margin-top: 1rem;
}

.monday-locations {
  border-left: 1px solid var(--accent);
  padding-left: 2.5rem;
}

.location-item {
  padding: 1rem 0;
  border-bottom: 1px solid var(--accent);
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.location-item:last-child {
  border-bottom: none;
}

.location-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-primary);
}

.location-detail {
  font-size: 0.82rem;
  color: var(--text-muted);
}

/* Memberships */
.memberships-intro {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  margin-bottom: 3rem;
}

.memberships-image img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  display: block;
}

.memberships-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  border-top: 1px solid var(--accent);
  padding-top: 2.5rem;
}

.membership-card {
  border: 1px solid var(--accent);
  padding: 2rem 1.75rem;
}

.membership-card h3 {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.membership-card p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* CTA link */
.cta-link {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--text-primary);
  text-decoration: none;
}

.cta-link:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Tinted section */
.section-tinted {
  background-color: #F3EDE5;
}

/* Handmade to Order — 2-col split heading + text */
.handmade-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

/* KatBox split layout (image left, text right) */
.katbox-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.katbox-split-image img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  display: block;
}

.katbox-split-text p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.75;
  margin-top: 1rem;
}

/* Monday image */
.monday-image img {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
  display: block;
}

/* Philosophy */
.philosophy-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
}

.philosophy-block h3 {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 1rem;
}

.philosophy-block p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.75;
}

.philosophy-list {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.philosophy-list li {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.7;
  padding-left: 1rem;
  position: relative;
}

.philosophy-list li::before {
  content: '—';
  position: absolute;
  left: 0;
  color: var(--accent);
}

/* Gallery */
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.gallery-item {
  margin: 0;
  position: relative;
  overflow: hidden;
}

.gallery-item img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease;
}

.gallery-item:hover img {
  transform: scale(1.03);
}

.gallery-item figcaption {
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-top: 0.6rem;
}

/* Contact grid */
.contact-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  border-top: 1px solid var(--accent);
  padding-top: 2rem;
}

/* Footer newsletter */
.footer-newsletter {
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--accent);
  margin-bottom: 2rem;
}

.footer-newsletter-heading {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.5rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

/* Footer */
footer {
  border-top: 1px solid var(--accent);
  padding: 2.5rem 0;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.footer-links {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.footer-links a {
  font-size: 0.78rem;
  color: var(--text-muted);
  text-decoration: none;
  letter-spacing: 0.02em;
}

.footer-links a:hover {
  color: var(--text-primary);
  text-decoration: underline;
}

.footer-copy {
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* Responsive */
@media (max-width: 768px) {
  .hamburger {
    display: flex;
  }

  nav.nav-links,
  .nav-instagram {
    display: none;
  }

  .features {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .steps-images {
    grid-template-columns: 1fr;
  }

  .steps-images img {
    height: 260px;
  }

  .hero-image {
    height: clamp(380px, 55vh, 520px);
  }

  .hero-overlay {
    padding: 0 1.25rem 2.5rem;
  }

  .hero-headline {
    font-size: clamp(3.5rem, 16vw, 6rem);
  }

  .section {
    padding: 4rem 0;
  }

  .section-image {
    max-height: 300px;
    margin: 3rem 0;
  }

  .katbox-layout,
  .monday-layout {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .monday-locations {
    border-left: none;
    border-top: 1px solid var(--accent);
    padding-left: 0;
    padding-top: 2rem;
  }

  .memberships-grid {
    grid-template-columns: 1fr;
  }

  .katbox-split,
  .handmade-layout,
  .philosophy-grid,
  .contact-grid,
  .memberships-intro {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  footer .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .steps-grid {
    grid-template-columns: 1fr 1fr;
  }

  .memberships-grid {
    grid-template-columns: 1fr 1fr;
  }

  .philosophy-grid {
    grid-template-columns: 1fr 1fr;
  }

  .gallery-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;0,700;1,300;1,400&family=DM+Sans:wght@300;400;500;600&display=swap');
@import "tailwindcss";

:root {
  --bg: #FAF7F2;
  --text-primary: #1A1A1A;
  --text-muted: #6B6B6B;
  --accent: #D9CFC4;
  --max-width: 1100px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg);
  color: var(--text-primary);
  font-family: 'DM Sans', sans-serif;
  font-size: 1rem;
  line-height: 1.7;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Typography */
.font-display {
  font-family: 'Cormorant Garamond', serif;
}

.eyebrow {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.section-heading {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 500;
  line-height: 1.2;
  color: var(--text-primary);
  margin-top: 0.5rem;
}

/* Navigation */
header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background-color: var(--bg);
  border-bottom: 1px solid transparent;
  transition: border-color 0.3s ease;
}

header.scrolled {
  border-bottom-color: var(--accent);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.nav-logo {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.4rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-primary);
  text-decoration: none;
  flex-shrink: 0;
}

.nav-logo img {
  height: 40px;
  width: auto;
}

nav.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

nav.nav-links a {
  font-size: 0.78rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--text-primary);
  position: relative;
  padding-bottom: 2px;
}

nav.nav-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background-color: var(--text-primary);
  transition: width 0.2s ease;
}

nav.nav-links a:hover::after {
  width: 100%;
}

.nav-instagram a {
  color: var(--text-primary);
  text-decoration: none;
  display: flex;
  align-items: center;
}

.nav-instagram a:hover {
  color: var(--text-muted);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background-color: var(--text-primary);
  transition: transform 0.3s ease, opacity 0.3s ease;
}

/* Mobile Nav Overlay */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  background-color: var(--bg);
  z-index: 99;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2rem;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  font-family: 'Cormorant Garamond', serif;
  font-size: 2rem;
  font-weight: 500;
  text-decoration: none;
  color: var(--text-primary);
  letter-spacing: 0.05em;
}

.mobile-nav a:hover {
  color: var(--text-muted);
}

.mobile-nav-close {
  position: absolute;
  top: 1.5rem;
  right: 1.5rem;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--text-primary);
  line-height: 1;
}

/* Hero */
.hero {
  padding-top: 70px;
}

.hero-banner {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.hero-image {
  width: 100%;
  height: clamp(480px, 70vh, 720px);
  object-fit: cover;
  display: block;
  /* lighten the photo so dark text reads clearly */
  filter: brightness(1.15) saturate(0.85);
}

/* warm cream wash over the image */
.hero-banner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(250, 247, 242, 0.45);
  pointer-events: none;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 0 1.5rem 3.5rem;
  max-width: calc(var(--max-width) + 3rem);
  margin: 0 auto;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
}

.hero-headline {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(5rem, 13vw, 9rem);
  font-weight: 600;
  line-height: 0.9;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--text-primary);
  margin: 0.6rem 0 0;
}

/* Below-image content area */
.hero-content {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2.5rem 1.5rem 3rem;
}

.hero-body {
  max-width: 560px;
  color: var(--text-muted);
  font-size: 1rem;
  line-height: 1.75;
}

.hero-body p + p {
  margin-top: 1rem;
}

/* Feature Row */
.features {
  border-top: 1px solid var(--accent);
  margin-top: 3rem;
  padding-top: 2.5rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.feature-item h4 {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--text-primary);
  margin-bottom: 0.3rem;
}

.feature-item p {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* Sections */
.section {
  padding: 6rem 0;
}

.section + .section {
  border-top: 1px solid var(--accent);
}

.section-header {
  margin-bottom: 3.5rem;
}

/* Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 4rem;
}

.step-number {
  font-family: 'Cormorant Garamond', serif;
  font-size: 5rem;
  font-weight: 300;
  line-height: 1;
  color: var(--accent);
  margin-bottom: 1rem;
}

.step h3 {
  font-family: 'DM Sans', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  margin-bottom: 0.6rem;
}

.step p {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.7;
}

.steps-images {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.steps-images img {
  width: 100%;
  height: 360px;
  object-fit: cover;
  display: block;
}

/* Menu */
.menu-status {
  border: 1px solid var(--accent);
  padding: 3rem;
  max-width: 480px;
}

.menu-status .status-label {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

.menu-status h3 {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.75rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.menu-status p {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* Bread collection image */
.section-image {
  width: 100%;
  max-height: 480px;
  object-fit: cover;
  display: block;
  margin: 4rem 0;
}

/* FAQ */
.faq-list {
  border-top: 1px solid var(--accent);
}

.faq-item {
  border-bottom: 1px solid var(--accent);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.4rem 0;
  cursor: pointer;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  gap: 1rem;
}

.faq-question span {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.4;
}

.faq-toggle {
  font-size: 1.2rem;
  font-weight: 300;
  color: var(--text-muted);
  transition: transform 0.25s ease;
  flex-shrink: 0;
  line-height: 1;
}

.faq-item.open .faq-toggle {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.25s ease;
}

.faq-answer-inner {
  padding-bottom: 1.4rem;
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.75;
  max-width: 680px;
}

.faq-item.open .faq-answer {
  max-height: 400px;
}

/* KatBox Section */
.katbox-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.katbox-text p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.75;
}

.katbox-text p + p {
  margin-top: 1rem;
}

.katbox-details {
  border: 1px solid var(--accent);
  padding: 2rem;
}

.katbox-detail-item {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.9rem 0;
  border-bottom: 1px solid var(--accent);
  font-size: 0.875rem;
}

.katbox-detail-item:last-child {
  border-bottom: none;
}

.katbox-detail-label {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.katbox-detail-item span:last-child {
  color: var(--text-primary);
}

/* Monday Sales */
.monday-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.monday-text p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.75;
}

.monday-text p + p {
  margin-top: 1rem;
}

.monday-locations {
  border-left: 1px solid var(--accent);
  padding-left: 2.5rem;
}

.location-item {
  padding: 1rem 0;
  border-bottom: 1px solid var(--accent);
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.location-item:last-child {
  border-bottom: none;
}

.location-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-primary);
}

.location-detail {
  font-size: 0.82rem;
  color: var(--text-muted);
}

/* Memberships */
.memberships-intro {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  margin-bottom: 3rem;
}

.memberships-image img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  display: block;
}

.memberships-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  border-top: 1px solid var(--accent);
  padding-top: 2.5rem;
}

.membership-card {
  border: 1px solid var(--accent);
  padding: 2rem 1.75rem;
}

.membership-card h3 {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.membership-card p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* CTA link */
.cta-link {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--text-primary);
  text-decoration: none;
}

.cta-link:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Tinted section */
.section-tinted {
  background-color: #F3EDE5;
}

/* Handmade to Order — 2-col split heading + text */
.handmade-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

/* KatBox split layout (image left, text right) */
.katbox-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.katbox-split-image img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  display: block;
}

.katbox-split-text p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.75;
  margin-top: 1rem;
}

/* Monday image */
.monday-image img {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
  display: block;
}

/* Philosophy */
.philosophy-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
}

.philosophy-block h3 {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 1rem;
}

.philosophy-block p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.75;
}

.philosophy-list {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.philosophy-list li {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.7;
  padding-left: 1rem;
  position: relative;
}

.philosophy-list li::before {
  content: '—';
  position: absolute;
  left: 0;
  color: var(--accent);
}

/* Gallery */
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.gallery-item {
  margin: 0;
  position: relative;
  overflow: hidden;
}

.gallery-item img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease;
}

.gallery-item:hover img {
  transform: scale(1.03);
}

.gallery-item figcaption {
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-top: 0.6rem;
}

/* Contact grid */
.contact-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  border-top: 1px solid var(--accent);
  padding-top: 2rem;
}

/* Footer newsletter */
.footer-newsletter {
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--accent);
  margin-bottom: 2rem;
}

.footer-newsletter-heading {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.5rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

/* Footer */
footer {
  border-top: 1px solid var(--accent);
  padding: 2.5rem 0;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.footer-links {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.footer-links a {
  font-size: 0.78rem;
  color: var(--text-muted);
  text-decoration: none;
  letter-spacing: 0.02em;
}

.footer-links a:hover {
  color: var(--text-primary);
  text-decoration: underline;
}

.footer-copy {
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* Responsive */
@media (max-width: 768px) {
  .hamburger {
    display: flex;
  }

  nav.nav-links,
  .nav-instagram {
    display: none;
  }

  .features {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .steps-images {
    grid-template-columns: 1fr;
  }

  .steps-images img {
    height: 260px;
  }

  .hero-image {
    height: clamp(380px, 55vh, 520px);
  }

  .hero-overlay {
    padding: 0 1.25rem 2.5rem;
  }

  .hero-headline {
    font-size: clamp(3.5rem, 16vw, 6rem);
  }

  .section {
    padding: 4rem 0;
  }

  .section-image {
    max-height: 300px;
    margin: 3rem 0;
  }

  .katbox-layout,
  .monday-layout {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .monday-locations {
    border-left: none;
    border-top: 1px solid var(--accent);
    padding-left: 0;
    padding-top: 2rem;
  }

  .memberships-grid {
    grid-template-columns: 1fr;
  }

  .katbox-split,
  .handmade-layout,
  .philosophy-grid,
  .contact-grid,
  .memberships-intro {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  footer .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .steps-grid {
    grid-template-columns: 1fr 1fr;
  }

  .memberships-grid {
    grid-template-columns: 1fr 1fr;
  }

  .philosophy-grid {
    grid-template-columns: 1fr 1fr;
  }

  .gallery-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* ── Primary Button ─────────────────────────────────────────── */
.btn-primary {
  display: inline-block;
  background-color: var(--text-primary);
  color: var(--bg);
  font-family: 'DM Sans', sans-serif;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 0.9rem 1.9rem;
  transition: opacity 0.2s ease;
  cursor: pointer;
  border: none;
}

.btn-primary:hover {
  opacity: 0.78;
}

/* ── Hero — tagline block below image (banhboxbakery style) ─── */
.hero-tagline-block {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 3rem 1.5rem 4rem;
  border-bottom: 1px solid var(--accent);
}

.hero-tagline {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(1.55rem, 3.2vw, 2.6rem);
  font-weight: 400;
  line-height: 1.35;
  color: var(--text-primary);
  max-width: 820px;
  margin-bottom: 2rem;
}

.hero-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-bottom: 0;
}

.pill {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  border: 1px solid var(--accent);
  padding: 0.38rem 0.85rem;
  color: var(--text-muted);
}

/* ── Nav Active State ────────────────────────────────────────── */
.nav-active {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* ── Section sub-heading helper ──────────────────────────────── */
.section-sub {
  margin-top: 0.75rem;
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.7;
  max-width: 560px;
}

/* ── About split (image + text) ──────────────────────────────── */
.about-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5rem;
  align-items: center;
}

.about-text p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.8;
  margin-top: 1rem;
}

.about-image img {
  width: 100%;
  aspect-ratio: 4/5;
  object-fit: cover;
  display: block;
}

/* ── Cookie Cards ────────────────────────────────────────────── */
.cookie-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  margin-bottom: 3rem;
}

.cookie-card {
  display: flex;
  flex-direction: column;
}

.cookie-card-image {
  position: relative;
  overflow: hidden;
}

.cookie-card-image img {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease;
}

.cookie-card:hover .cookie-card-image img {
  transform: scale(1.04);
}

.cookie-tag {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  font-size: 0.63rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--bg);
  color: var(--text-primary);
  padding: 0.28rem 0.65rem;
}

.cookie-card-body {
  padding: 1rem 0;
}

.cookie-card-body h3 {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.2rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 0.35rem;
}

.cookie-card-body p {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* Mystery / tease cards */
.cookie-card-image-mystery {
  aspect-ratio: 3/4;
  background: #EDE8E1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.mystery-placeholder {
  font-family: 'Cormorant Garamond', serif;
  font-size: 5rem;
  font-weight: 300;
  color: var(--accent);
  line-height: 1;
}

.cookie-card-tease .cookie-card-body h3,
.cookie-card-tease .cookie-card-body p {
  font-style: italic;
  color: var(--text-muted);
}

.cookie-cta,
.how-cta {
  text-align: center;
}

/* ── How It Works ────────────────────────────────────────────── */
.how-steps {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 3rem;
  margin-bottom: 3.5rem;
  border-top: 1px solid var(--accent);
  padding-top: 2.5rem;
}

.how-step-number {
  font-family: 'Cormorant Garamond', serif;
  font-size: 4.5rem;
  font-weight: 300;
  line-height: 1;
  color: var(--accent);
  margin-bottom: 1rem;
}

.how-step-content h3 {
  font-family: 'DM Sans', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.6rem;
}

.how-step-content p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.7;
}

.how-step-content a {
  color: var(--text-primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}

/* ── Mission / Social Proof (dark section) ───────────────────── */
.section-dark {
  background-color: #262220;
}

.section-dark .eyebrow {
  color: #897E72;
}

.mission-inner {
  max-width: 780px;
  margin: 0 auto;
  text-align: center;
}

.mission-quote {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  font-weight: 400;
  font-style: italic;
  line-height: 1.55;
  color: #F5F0E8;
  margin-bottom: 1.5rem;
}

.mission-byline {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #897E72;
  margin-bottom: 4rem;
}

.trust-badges {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  border-top: 1px solid #3D3730;
  padding-top: 3rem;
  text-align: left;
}

.trust-badge {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.trust-badge-title {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.9rem;
  font-weight: 600;
  color: #F5F0E8;
  letter-spacing: 0.03em;
}

.trust-badge-sub {
  font-size: 0.82rem;
  color: #897E72;
  line-height: 1.65;
}

/* ── Contact ─────────────────────────────────────────────────── */
.contact-link {
  font-size: 0.95rem;
  color: var(--text-primary);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.contact-detail {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* ── Footer newsletter sub ───────────────────────────────────── */
.footer-newsletter-sub {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.7;
  margin-top: 0.4rem;
  max-width: 520px;
}

.footer-cta-row {
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
  margin-top: 1rem;
}

/* ═══════════════════════════════════════════════════════════════
   ORDER PAGE
═══════════════════════════════════════════════════════════════ */

.order-hero {
  padding-top: calc(70px + 5rem);
  padding-bottom: 3.5rem;
  border-bottom: 1px solid var(--accent);
}

.order-heading {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(2.5rem, 7vw, 5rem);
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.05;
  margin: 0.5rem 0 1rem;
}

.order-sub {
  font-size: 0.95rem;
  color: var(--text-muted);
  max-width: 480px;
}

/* Status Panel */
.order-status-section {
  padding-bottom: 0;
}

.status-panel {
  border: 1px solid var(--accent);
  padding: 3rem;
  max-width: 620px;
}

.status-panel.status-open {
  border-color: #4A7C59;
  background: #F5FAF6;
}

.status-badge {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}

.status-badge-open   { color: #2D6A45; }
.status-badge-closed { color: #9A4A2A; }

.status-heading {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(1.75rem, 3.5vw, 2.4rem);
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.status-text {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.status-date {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 2rem;
}

.status-closes {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.status-cta-hint {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-top: 1.5rem;
}

.status-cta-hint a {
  color: var(--text-primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}

/* Countdown Timer */
.countdown {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.countdown-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4rem;
  min-width: 72px;
}

.countdown-num {
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(2.8rem, 5vw, 4rem);
  font-weight: 300;
  line-height: 1;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.countdown-label {
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.countdown-sep {
  font-family: 'Cormorant Garamond', serif;
  font-size: 3.5rem;
  font-weight: 300;
  color: var(--accent);
  line-height: 1;
  padding-top: 0.15rem;
}

/* SMS Form */
.sms-block {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5rem;
  align-items: start;
}

.sms-text p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.8;
  margin-top: 1rem;
}

.sms-benefits {
  list-style: none;
  padding: 0;
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.sms-benefits li {
  font-size: 0.875rem;
  color: var(--text-muted);
  padding-left: 1.4rem;
  position: relative;
  line-height: 1.5;
}

.sms-benefits li::before {
  content: '✓';
  position: absolute;
  left: 0;
  color: var(--text-primary);
  font-weight: 700;
}

.sms-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-field label {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.form-field input,
.form-field select {
  width: 100%;
  padding: 0.8rem 1rem;
  border: 1px solid var(--accent);
  background: var(--bg);
  color: var(--text-primary);
  font-family: 'DM Sans', sans-serif;
  font-size: 0.9rem;
  outline: none;
  transition: border-color 0.2s ease;
  appearance: none;
  border-radius: 0;
}

.form-field input:focus,
.form-field select:focus {
  border-color: var(--text-primary);
}

.form-field input::placeholder {
  color: #B0A898;
}

.form-disclaimer {
  font-size: 0.72rem;
  color: var(--text-muted);
  line-height: 1.55;
}

.form-submit {
  width: 100%;
  text-align: center;
  justify-content: center;
  font-family: 'DM Sans', sans-serif;
}

.form-success {
  background: #F0F7F2;
  border: 1px solid #4A7C59;
  color: #2D6A45;
  padding: 1rem 1.25rem;
  font-size: 0.9rem;
  text-align: center;
  font-weight: 500;
}

/* ═══════════════════════════════════════════════════════════════
   RESPONSIVE — new components
═══════════════════════════════════════════════════════════════ */

@media (max-width: 768px) {
  .hero-tagline-block {
    padding: 2.5rem 1.25rem 3rem;
  }

  .hero-tagline {
    font-size: clamp(1.3rem, 5.5vw, 1.8rem);
  }

  .about-split {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .cookie-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1rem;
  }

  .how-steps {
    grid-template-columns: 1fr;
    gap: 2rem;
    padding-top: 2rem;
  }

  .trust-badges {
    grid-template-columns: 1fr;
    gap: 1.75rem;
    text-align: center;
  }

  .sms-block {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .countdown {
    gap: 0.3rem;
  }

  .countdown-num {
    font-size: 2.4rem;
  }

  .countdown-item {
    min-width: 52px;
  }

  .countdown-sep {
    font-size: 2rem;
  }

  .order-hero {
    padding-top: calc(70px + 3rem);
    padding-bottom: 2.5rem;
  }

  .status-panel {
    padding: 2rem 1.5rem;
  }

  .footer-cta-row {
    flex-direction: column;
    gap: 0.75rem;
  }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .cookie-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .how-steps {
    grid-template-columns: repeat(2, 1fr);
  }

  .sms-block {
    gap: 3rem;
  }
}

---
import Layout from '../layouts/Layout.astro';
import type { MenuItem } from '../types/MenuItem';
import { getBestSellers, getMenuItems, getNewItems } from '../lib/db';
export const prerender = true

const CDN_URL = import.meta.env.PUBLIC_SUPABASE_STORAGE_URL;

// Fetch all three datasets
const allItems    = await getMenuItems();
const bestSellers = await getBestSellers();
const newItems    = await getNewItems();

// Build lookup sets so each item can be tagged
const bestSellerIds = new Set(bestSellers.map(b => b.menuItem.id));
const newItemIds    = new Set(newItems.map(n => n.menuItem.id));

// Returns space-separated filter tokens used by the JS filter
function getItemDataTags(item: MenuItem): string {
  const tags = ['all'];
  if (newItemIds.has(item.id))    tags.push('this-drop');
  if (bestSellerIds.has(item.id)) tags.push('bestseller');
  return tags.join(' ');
}

// Returns the primary badge to show on the card image (most specific first)
function getItemBadge(item: MenuItem): { text: string; cls: string } | null {
  if (item.mystery)               return null;
  if (newItemIds.has(item.id))    return { text: 'This Drop',  cls: 'stock-badge-available' };
  if (bestSellerIds.has(item.id)) return { text: 'Bestseller', cls: 'stock-badge-coming-soon' };
  return null;
}
---

<Layout
  title="Menu — Katered Kneads"
  description="Browse the full Katered Kneads catalog. Small-batch handmade cookies — the lineup rotates every biweekly drop."
  activePage="menu"
>

  <!-- Page Header -->
  <section class="order-hero">
    <div class="container">
      <p class="eyebrow">Our Catalog</p>
      <h1 class="order-heading">The Menu</h1>
      <p class="order-sub">
        Every item we've ever offered — updated each drop. Not everything is available at every drop.
        Check the <a href="/order" style="color:var(--text-primary);text-decoration:underline;text-underline-offset:2px;">order page</a> for what's live right now.
      </p>
    </div>
  </section>

  <!-- Catalog -->
  <section class="section" id="catalog">
    <div class="container">

      <!-- Rotating-menu notice -->
      <div class="menu-note">
        <strong>Heads up:</strong> This is a living catalog — items rotate in and out each drop. Follow us on
        <a href="https://www.instagram.com/Katered_Kneads" target="_blank" rel="noopener noreferrer">Instagram</a>
        or <a href="/order#sms-signup">join the SMS list</a> to know exactly what's in the next drop.
      </div>

      <!-- Filter Tabs -->
      <div class="filter-tabs" role="tablist" aria-label="Filter menu items">
        <button class="filter-btn active" data-filter="all"        role="tab" aria-selected="true">All Items</button>
        <button class="filter-btn"        data-filter="this-drop"  role="tab" aria-selected="false">This Drop</button>
        <button class="filter-btn"        data-filter="bestseller" role="tab" aria-selected="false">Bestsellers</button>
      </div>

      <!-- Item Grid -->
      {allItems.length > 0 ? (
        <div class="product-grid" id="catalog-grid">

          {allItems.map(item => {
            const badge    = getItemBadge(item);
            const dataTags = getItemDataTags(item);
            return (
              <div
                class={`product-card${item.mystery ? ' product-card-mystery' : ''}`}
                data-tags={dataTags}
              >
                <div class="product-card-image">
                  {item.mystery
                    ? <div class="mystery-placeholder">?</div>
                    : <img src={CDN_URL + item.id} alt={item.name} loading="lazy" />
                  }
                  {badge && (
                    <span class={`stock-badge ${badge.cls}`}>{badge.text}</span>
                  )}
                </div>
                <div class="product-card-body">
                  <h3>{item.mystery ? '???' : item.name}</h3>
                  <p>{item.mystery ? 'Revealed when orders open.' : item.description}</p>
                </div>
              </div>
            );
          })}

          <!-- Shown via JS when a filter returns zero results -->
          <div class="catalog-empty" id="no-results" style="display:none;">
            No items match this filter right now — check back after the next drop.
          </div>

        </div>
      ) : (
        <!-- Empty state when DB has no items yet -->
        <div class="drop-placeholder">
          <p class="eyebrow">Menu Coming Soon</p>
          <p>Our catalog is being updated. Follow us on Instagram or join the SMS list to see what's dropping next.</p>
          <div style="margin-top:1.5rem;">
            <a href="/order#sms-signup" class="btn-primary">Join SMS List →</a>
          </div>
        </div>
      )}

      <div style="margin-top:3rem;display:flex;gap:1.5rem;flex-wrap:wrap;align-items:center;border-top:1px solid var(--accent);padding-top:2rem;">
        <a href="/order" class="btn-primary">Place a Preorder →</a>
        <a href="/order#sms-signup" class="btn-secondary">Join SMS List →</a>
      </div>

    </div>
  </section>

</Layout>

<script>
  const filterBtns = document.querySelectorAll<HTMLButtonElement>('.filter-btn');
  const cards      = document.querySelectorAll<HTMLElement>('.product-card');
  const noResults  = document.getElementById('no-results');

  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const filter = btn.dataset.filter ?? 'all';

      // Update active tab state
      filterBtns.forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-selected', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-selected', 'true');

      // Show / hide cards
      let visible = 0;
      cards.forEach(card => {
        const tags = card.dataset.tags ?? '';
        const show = filter === 'all' || tags.split(' ').includes(filter);
        card.style.display = show ? '' : 'none';
        if (show) visible++;
      });

      // Empty state
      if (noResults) {
        noResults.style.display = visible === 0 ? 'block' : 'none';
      }
    });
  });
</script>

---
import Layout from '../layouts/Layout.astro';
import type { MenuItem } from '../types/MenuItem';
import { getMenuItems, getNewItems } from '../lib/db';
export const prerender = true

const CDN_URL = import.meta.env.PUBLIC_SUPABASE_STORAGE_URL;

const allItems = await getMenuItems();
const newItems = await getNewItems();

const newItemIds = new Set(newItems.map(n => n.menuItem.id));

function getItemDataTags(item: MenuItem): string {
  return newItemIds.has(item.id) ? 'all this-drop' : 'all';
}

function getItemBadge(item: MenuItem): { text: string; cls: string } | null {
  if (item.mystery || !newItemIds.has(item.id)) return null;
  return { text: 'This Drop', cls: 'stock-badge-available' };
}
