import { defineMiddleware } from 'astro:middleware';
import { createAnonClient } from './lib/supabase';

export const onRequest = defineMiddleware(async (context, next) => {
  const { pathname } = context.url;

  // Protect all /admin routes except /admin/login
  if (pathname.startsWith('/admin') && !pathname.startsWith('/admin/login')) {
    const accessToken = context.cookies.get('sb-access-token')?.value;

    if (!accessToken) {
      return context.redirect('/admin/login');
    }

    // Verify the token with Supabase
    const supabase = createAnonClient();
    const { data: { user }, error } = await supabase.auth.getUser(accessToken);

    if (error || !user) {
      context.cookies.delete('sb-access-token', { path: '/' });
      context.cookies.delete('sb-refresh-token', { path: '/' });
      return context.redirect('/admin/login');
    }

    // Make user available to all admin pages
    (context.locals as Record<string, unknown>).user = user;
  }

  // Redirect already-logged-in users away from login page
  if (pathname.startsWith('/admin/login')) {
    const accessToken = context.cookies.get('sb-access-token')?.value;
    if (accessToken) {
      const supabase = createAnonClient();
      const { data: { user } } = await supabase.auth.getUser(accessToken);
      if (user) return context.redirect('/admin');
    }
  }

  return next();
});

import { defineMiddleware } from 'astro:middleware';
import { createAnonClient } from './lib/supabase';

function isAdminRoute(pathname: string) {
  // Match /admin, /admin/, /admin/anything — but NOT /admin/login[/]
  const normalized = pathname.endsWith('/') && pathname !== '/' ? pathname.slice(0, -1) : pathname;
  if (normalized === '/admin/login') return false;
  return normalized === '/admin' || normalized.startsWith('/admin/');
}

function isLoginRoute(pathname: string) {
  const normalized = pathname.endsWith('/') ? pathname.slice(0, -1) : pathname;
  return normalized === '/admin/login';
}

export const onRequest = defineMiddleware(async (context, next) => {
  const { pathname } = context.url;

  // Protect all /admin routes except /admin/login
  if (isAdminRoute(pathname)) {
    const accessToken = context.cookies.get('sb-access-token')?.value;

    if (!accessToken) {
      return context.redirect('/admin/login');
    }

    // Verify the token with Supabase
    const supabase = createAnonClient();
    const { data: { user }, error } = await supabase.auth.getUser(accessToken);

    if (error || !user) {
      context.cookies.delete('sb-access-token', { path: '/' });
      context.cookies.delete('sb-refresh-token', { path: '/' });
      return context.redirect('/admin/login');
    }

    (context.locals as Record<string, unknown>).user = user;
  }

  // Redirect already-logged-in users away from login page
  if (isLoginRoute(pathname)) {
    const accessToken = context.cookies.get('sb-access-token')?.value;
    if (accessToken) {
      const supabase = createAnonClient();
      const { data: { user } } = await supabase.auth.getUser(accessToken);
      if (user) return context.redirect('/admin');
    }
  }

  return next();
});

import type { APIRoute } from 'astro';
import { createServerClient } from '../../../lib/supabase';

export const POST: APIRoute = async ({ request }) => {
  try {
    const formData = await request.formData();
    const file = formData.get('file') as File | null;
    const existingId = formData.get('id') as string | null;

    if (!file) {
      return new Response(JSON.stringify({ error: 'No file provided' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    const uuid = existingId ?? crypto.randomUUID();
    const arrayBuffer = await file.arrayBuffer();
    const supabase = createServerClient();

    const { error } = await supabase.storage
      .from('item_images')
      .upload(uuid, arrayBuffer, {
        contentType: file.type,
        upsert: !!existingId,
      });

    if (error) throw error;

    return new Response(JSON.stringify({ uuid }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error';
    return new Response(JSON.stringify({ error: message }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }
};
